<?php [$from,$to,$category,$payment]=$data['filters']; ?>
<div class="page-heading"><div><p class="eyebrow">ANGKA DI BALIK CERITA</p><h1>Laporan penjualan</h1><p class="page-subtitle">Telusuri transaksi dan ringkasan pendapatan kafe.</p></div><div class="heading-actions"><a class="button button-quiet" href="<?=e(url('reports',['from'=>$from,'to'=>$to,'category'=>$category,'payment'=>$payment,'export'=>'csv']))?>">Unduh CSV</a><button class="button button-primary" onclick="window.print()">Cetak / simpan PDF</button></div></div>
<section class="panel filter-panel"><form method="get" class="filter-form"><input type="hidden" name="page" value="reports"><label>Dari tanggal<input type="date" name="from" value="<?=e($from)?>"></label><label>Sampai tanggal<input type="date" name="to" value="<?=e($to)?>"></label><label>Kategori menu<select name="category"><option value="0">Semua kategori</option><?php foreach($data['categories'] as $c):?><option value="<?=$c['id']?>" <?=$category===$c['id']?'selected':''?>><?=e($c['name'])?></option><?php endforeach?></select></label><label>Metode bayar<select name="payment"><option value="">Semua metode</option><?php foreach(['cash'=>'Tunai','qris'=>'QRIS','transfer'=>'Transfer','debit'=>'Kartu debit'] as $k=>$v):?><option value="<?=$k?>" <?=$payment===$k?'selected':''?>><?=$v?></option><?php endforeach?></select></label><button class="button button-primary">Terapkan filter</button></form></section>
<section class="report-kpis"><article class="report-kpi"><small>Omzet kotor</small><strong><?=rupiah($data['summary']['gross'])?></strong><span>Sebelum diskon</span></article><article class="report-kpi"><small>Total diskon</small><strong><?=rupiah($data['summary']['discount'])?></strong><span>Potongan pesanan sah</span></article><article class="report-kpi"><small>Pajak terkumpul</small><strong><?=rupiah($data['summary']['tax'])?></strong><span>Pajak restoran</span></article><article class="report-kpi"><small>Omzet bersih</small><strong><?=rupiah($data['summary']['revenue'])?></strong><span>Setelah diskon, sebelum pajak</span></article><article class="report-kpi"><small>Rata-rata transaksi</small><strong><?=rupiah($data['summary']['count']?$data['summary']['charged']/$data['summary']['count']:0)?></strong><span><?=number_format($data['summary']['count'])?> pesanan</span></article></section>
<section class="panel report-table"><div class="panel-head"><div><h2>Rincian transaksi</h2><p><?=e(date_id($from))?> sampai <?=e(date_id($to))?> · <?=count($data['rows'])?> baris</p></div></div><div class="table-scroll"><table><thead><tr><th>No. faktur</th><th>Tanggal & jam</th><th>Kasir</th><th>Jenis</th><th>Item terjual</th><th>Subtotal</th><th>Pajak</th><th>Total</th><th>Status</th></tr></thead><tbody><?php foreach($data['rows'] as $o):?><tr><td class="invoice-cell"><?=e($o['invoice_number'])?></td><td><?=e(date('d/m/Y H:i',strtotime($o['created_at'])))?></td><td><?=e($o['cashier'])?></td><td><?=$o['order_type']==='dine_in'?'Dine in':'Takeaway'?></td><td><?=e($o['item_names']??'')?> <small>(<?=$o['item_quantity']?>)</small></td><td><?=rupiah($o['subtotal'])?></td><td><?=rupiah($o['tax_amount'])?></td><td class="money-cell"><?=rupiah($o['grand_total'])?></td><td><span class="status status-<?=e($o['status'])?>"><?=e(status_label($o['status']))?></span></td></tr><?php endforeach;if(!$data['rows']):?><tr><td colspan="9" class="table-empty">Tidak ada transaksi untuk filter ini.</td></tr><?php endif?></tbody><tfoot><tr><th colspan="7">Omzet bersih</th><th><?=rupiah($data['summary']['revenue'])?></th><th></th></tr></tfoot></table></div></section>
